begin;
set local search_path=public,extensions;
select plan(28);
grant usage on schema extensions to authenticated;
grant execute on all functions in schema extensions to authenticated;

select ok((select count(*)=9 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relkind='r'and c.relname=any(array['dispute_cases','dispute_evidence','dispute_responses','dispute_decisions','dispute_financial_consequences','provider_performance_events','mission_reassignments','dispute_appeals','dispute_case_events'])),'all dispute, evidence, consequence, appeal and reassignment tables exist');
select ok((select count(*)=9 and bool_and(c.relrowsecurity)from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['dispute_cases','dispute_evidence','dispute_responses','dispute_decisions','dispute_financial_consequences','provider_performance_events','mission_reassignments','dispute_appeals','dispute_case_events'])),'RLS is enabled on every dispute table');
select ok((select count(*)=10 and count(distinct tablename)=9 from pg_policies where schemaname='public'and tablename=any(array['dispute_cases','dispute_evidence','dispute_responses','dispute_decisions','dispute_financial_consequences','provider_performance_events','mission_reassignments','dispute_appeals','dispute_case_events'])) and exists(select 1 from pg_policies where schemaname='public' and policyname='dispute_cases_franchise_library_read' and qual like '%franchise_supervises_dispute%'),'each dispute table has an explicit scoped read policy');
select ok((select count(*)=7 and bool_and(p.prosecdef and p.proconfig::text like'%search_path=%')from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['open_mission_dispute','respond_to_mission_dispute','decide_mission_dispute','appeal_mission_dispute','propose_mission_reassignment','approve_reassignment_cost','activate_mission_reassignment'])),'seven public commands are security definer with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['open_mission_dispute','respond_to_mission_dispute','decide_mission_dispute','appeal_mission_dispute','propose_mission_reassignment','approve_reassignment_cost','activate_mission_reassignment'])and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anonymous and service roles cannot execute user dispute commands');
select ok((select count(*)=7 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE'))from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname=any(array['open_mission_dispute','respond_to_mission_dispute','decide_mission_dispute','appeal_mission_dispute','propose_mission_reassignment','approve_reassignment_cost','activate_mission_reassignment'])),'authenticated users have only explicit command execution');
select ok(not has_table_privilege('authenticated','public.dispute_cases','INSERT')and not has_table_privilege('authenticated','public.dispute_decisions','UPDATE')and not has_table_privilege('authenticated','public.mission_reassignments','UPDATE'),'direct case, decision and reassignment mutation is denied');
select ok(not has_table_privilege('authenticated','public.dispute_evidence','INSERT')and not has_table_privilege('authenticated','public.dispute_financial_consequences','DELETE'),'direct evidence and financial consequence mutation is denied');
select ok((select count(*)=7 from pg_trigger where tgname=any(array['dispute_evidence_immutable','dispute_responses_immutable','dispute_decisions_immutable','dispute_consequences_immutable','provider_performance_events_immutable','dispute_appeals_immutable','dispute_case_events_immutable'])and not tgisinternal),'evidence, responses, decisions, consequences, appeals and history are immutable');
select ok((select data_type='bigint'from information_schema.columns where table_schema='public'and table_name='dispute_financial_consequences'and column_name='amount_minor'),'all dispute money is represented in exact minor units');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name in('dispute_financial_consequences','mission_reassignments')and data_type in('real','double precision')),'no floating-point financial column exists');
select ok((select count(*)=4 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname in('dispute_case_access','dispute_evidence_access','dispute_financial_access','dispute_reassignment_access')and p.prosecdef),'case, evidence, financial and reassignment access use protected security-definer predicates');
select ok((select pg_get_functiondef(p.oid)like'%DISPUTE_MANAGER%'and pg_get_functiondef(p.oid)like'%BOTH_PARTIES%'and pg_get_functiondef(p.oid)like'%CLIENT_ONLY%'and pg_get_functiondef(p.oid)like'%PROVIDER_ONLY%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname='dispute_evidence_access'),'evidence visibility separates mediator and both parties');
select ok((select pg_get_functiondef(p.oid)like'%WARNING_LEVEL_1%'and pg_get_functiondef(p.oid)like'%jsonb_array_length(p_evidence)=0%'and pg_get_functiondef(p.oid)like'%DisputeWarningIssuedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='open_mission_dispute'),'opening creates a warning, requires evidence and notifies through Outbox');
select ok((select pg_get_functiondef(p.oid)like'%PROVIDER_OWNER%'and pg_get_functiondef(p.oid)like'%MEDIATION_REVIEW%'and pg_get_functiondef(p.oid)like'%STALE_DISPUTE_STATE%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='respond_to_mission_dispute'),'provider response is role-scoped and enters mediation with optimistic locking');
select ok((select pg_get_functiondef(p.oid)like'%DISPUTE_MANAGER%'and pg_get_functiondef(p.oid)like'%DISPUTE_DECISION_DENIED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_mission_dispute'),'only an authorized human dispute manager can decide');
select ok((select pg_get_functiondef(p.oid)like'%VALIDATED_CONTRACT_RULE_REQUIRED%'and pg_get_functiondef(p.oid)like'%penalty_minor%'and pg_get_functiondef(p.oid)like'%commission_minor%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_mission_dispute'),'punitive consequences require a versioned validated contract rule');
select ok((select pg_get_functiondef(p.oid)like'%CONTRACTUAL_PENALTY%'and pg_get_functiondef(p.oid)like'%MATRICIA_COMMISSION%'and pg_get_functiondef(p.oid)like'%NON_COMPLIANCE_CONFIRMED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_mission_dispute'),'confirmed non-compliance creates penalty, commission and performance evidence atomically');
select ok((select pg_get_functiondef(p.oid)like'%status=''CANCELLED''%'and pg_get_functiondef(p.oid)like'%mission_reassignments%'and pg_get_functiondef(p.oid)like'%DisputeNonComplianceConfirmedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_mission_dispute'),'confirmed non-compliance retires the source assignment, creates R1 and emits Outbox');
select ok((select pg_get_functiondef(p.oid)like'%REVERSAL%'and pg_get_functiondef(p.oid)like'%NON_COMPLIANCE_REVERSED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='decide_mission_dispute'),'appeal reversal appends compensating records instead of mutating financial history');
select ok((select pg_get_functiondef(p.oid)like'%clock_timestamp()>d.appeal_due_at%'and pg_get_functiondef(p.oid)like'%APPEALED%'and pg_get_functiondef(p.oid)like'%DisputeAppealedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='appeal_mission_dispute'),'appeal enforces the deadline and preserves contradictory procedure');
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_APPROVAL_REQUIRED%'and pg_get_functiondef(p.oid)like'%cost_delta_minor%'and pg_get_functiondef(p.oid)like'%FRAMEWORK_RATE%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='propose_mission_reassignment'),'replacement proposal calculates exact cost delta and gates increases');
select ok((select pg_get_functiondef(p.oid)like'%CLIENT_OWNER%'and pg_get_functiondef(p.oid)like'%REASSIGNMENT_APPROVED%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='approve_reassignment_cost'),'only the client can approve a higher replacement cost');
select ok((select pg_get_functiondef(p.oid)like'%appeal_due_at%'and pg_get_functiondef(p.oid)like'%replacement_contract_id%'and pg_get_functiondef(p.oid)like'%MissionReassignedV1%'from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='activate_mission_reassignment'),'activation waits for appeal safety and requires replacement contract and mission lineage');
select ok((select count(*)>=4 from pg_constraint where conrelid='public.mission_reassignments'::regclass and contype='f'),'reassignment preserves source, root, dispute and replacement lineage with foreign keys');
select ok((select is_generated='ALWAYS'from information_schema.columns where table_schema='public'and table_name='mission_reassignments'and column_name='reassignment_key'),'R1/R2 labels are derived from the immutable sequence number');
select ok((select count(*)>=7 from pg_indexes where schemaname='public'and tablename=any(array['dispute_cases','dispute_evidence','dispute_decisions','dispute_case_events','mission_reassignments'])),'case, deadline, evidence, decision and reassignment access paths are indexed');
select ok((select count(*)=1 from pg_constraint where conrelid='public.dispute_financial_consequences'::regclass and contype='u'and pg_get_constraintdef(oid)like'%consequence_type%'and pg_get_constraintdef(oid)like'%direction%'),'retries cannot duplicate a penalty, commission or reversal');

select * from finish();
rollback;
